import os
import json
import csv
import sys

ROOT = os.path.dirname(os.path.abspath(__file__))

def walk(path, depth=0):
    for entry in sorted(os.listdir(path)):
        full = os.path.join(path, entry)
        rel = os.path.relpath(full, ROOT)
        if os.path.isdir(full):
            print("DIR : " + rel + "/")
            walk(full, depth + 1)
        else:
            print("FILE: " + rel)

print("=== DIRECTORY TREE ===")
walk(ROOT)
print()

data_exts = (".csv", ".json", ".txt", ".tsv", ".log", ".md")

for dirpath, dirnames, filenames in os.walk(ROOT):
    for name in sorted(filenames):
        if name == os.path.basename(__file__):
            continue
        full = os.path.join(dirpath, name)
        rel = os.path.relpath(full, ROOT)
        ext = os.path.splitext(name)[1].lower()
        size = os.path.getsize(full)
        print(f"=== CONTENT: {rel} (size={size} bytes) ===")
        if ext in data_exts or size < 200_000:
            try:
                with open(full, "r", encoding="utf-8", errors="replace") as fh:
                    text = fh.read()
                if ext == ".csv":
                    # print first 40 lines to get a feel
                    lines = text.splitlines()
                    print("\n".join(lines[:40]))
                    print(f"... ({len(lines)} total lines)")
                elif ext == ".json":
                    try:
                        data = json.loads(text)
                        print(json.dumps(data, indent=2, ensure_ascii=False)[:12000])
                    except Exception as e:
                        print(text[:12000])
                else:
                    print(text[:12000])
            except Exception as e:
                print(f"ERROR reading: {e}")
        else:
            print(f"(skipped binary/large file)")
        print()

