import os
import csv
import json

ROOT = os.path.dirname(os.path.abspath(__file__))

def tree(path, depth=0):
    for entry in sorted(os.listdir(path)):
        full = os.path.join(path, entry)
        rel = os.path.relpath(full, ROOT)
        if os.path.isdir(full):
            print("DIR : " + rel + "/")
            tree(full, depth + 1)
        else:
            print("FILE: " + rel + f"  ({os.path.getsize(full)} bytes)")

print("=== DIRECTORY TREE ===")
tree(ROOT)
print()

for dirpath, dirnames, filenames in os.walk(ROOT):
    dirnames[:] = [d for d in sorted(dirnames) if d != ".codex"]
    for name in sorted(filenames):
        if name.endswith(".py"):
            continue
        full = os.path.join(dirpath, name)
        rel = os.path.relpath(full, ROOT)
        ext = os.path.splitext(name)[1].lower()
        print(f"=== CONTENT: {rel} ===")
        try:
            if ext == ".csv":
                with open(full, "r", encoding="utf-8", errors="replace") as fh:
                    reader = csv.reader(fh)
                    rows = list(reader)
                print(f"(rows incl header: {len(rows)}, cols: {len(rows[0]) if rows else 0})")
                for i, row in enumerate(rows):
                    print(f"R{i}: {row}")
            elif ext == ".json":
                with open(full, "r", encoding="utf-8", errors="replace") as fh:
                    text = fh.read()
                try:
                    print(json.dumps(json.loads(text), indent=2, ensure_ascii=False))
                except Exception:
                    print(text)
            elif ext in (".txt", ".md", ".tsv", ".log"):
                with open(full, "r", encoding="utf-8", errors="replace") as fh:
                    print(fh.read())
            else:
                print("(binary or unknown type)")
        except Exception as e:
            print(f"ERROR reading: {e}")
        print()

